{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.coupons import apply_coupons"
  ],
  "tests": [
    {
      "name": "test_example_from_task",
      "intent": "the example given in the task: 30% then 20% off 100.00 is 56.00",
      "code": "# intent: the example given in the task: 30% then 20% off 100.00 is 56.00\ndef test_example_from_task():\n    assert apply_coupons(Decimal(\"100.00\"), [Decimal(\"30\"), Decimal(\"20\")]) == Decimal(\"56.00\")\n"
    },
    {
      "name": "test_apply_one_coupon",
      "intent": "a single coupon applies its percentage to the original price",
      "code": "# intent: a single coupon applies its percentage to the original price\ndef test_apply_one_coupon():\n    assert apply_coupons(Decimal(\"100.00\"), [Decimal(\"25\")]) == Decimal(\"75.00\")\n"
    },
    {
      "name": "test_apply_no_coupons_keeps_the_price",
      "intent": "empty coupon list returns the original price unchanged",
      "code": "# intent: empty coupon list returns the original price unchanged\ndef test_apply_no_coupons_keeps_the_price():\n    assert apply_coupons(Decimal(\"100.00\"), []) == Decimal(\"100.00\")\n"
    },
    {
      "name": "test_apply_coupons_rejects_more_than_100_percent",
      "intent": "a coupon over 100% raises ValueError",
      "code": "# intent: a coupon over 100% raises ValueError\ndef test_apply_coupons_rejects_more_than_100_percent():\n    with pytest.raises(ValueError):\n        apply_coupons(Decimal(\"100.00\"), [Decimal(\"120\")])\n"
    },
    {
      "name": "test_apply_coupons_rejects_negative_percent",
      "intent": "a negative coupon percentage raises ValueError",
      "code": "# intent: a negative coupon percentage raises ValueError\ndef test_apply_coupons_rejects_negative_percent():\n    with pytest.raises(ValueError):\n        apply_coupons(Decimal(\"100.00\"), [Decimal(\"-10\")])\n"
    },
    {
      "name": "test_apply_coupons_rounds_to_cent_after_each_coupon",
      "intent": "intermediate results are rounded to cents using ROUND_HALF_UP",
      "code": "# intent: intermediate results are rounded to cents using ROUND_HALF_UP\ndef test_apply_coupons_rounds_to_cent_after_each_coupon():\n    # 100.00 * 0.333 = 33.3 -> 33.30; then 33.30 * 0.5 = 16.65\n    assert apply_coupons(Decimal(\"100.00\"), [Decimal(\"33.3\"), Decimal(\"50\")]) == Decimal(\"16.65\")\n"
    }
  ]
}
